from pathlib import Path
import json,hashlib,shutil
from pokemon_index import core,number_evidence,source_image_facts,discovery_graph,collector_journey
r=Path('catalog/source-facts-escalation-v1');old=Path('/tmp/pokemon-source-facts-thousand-v1.sqlite3');working=Path('/tmp/pokemon-source-facts-escalation-working-v2.sqlite3');assert not working.exists();shutil.copy2(old,working)
def rows(path):return list(map(json.loads,Path(path).read_text().splitlines()))
with core.connect(working) as db:
 number_evidence.import_evidence(db,rows(r/'number-evidence-v1.jsonl'));source_image_facts.import_evidence(db,rows(r/'evidence-v1.jsonl'))
 for path in ['catalog/cross-release-artwork-v1/verified-artwork-events-v2.jsonl','catalog/cross-release-artwork-v1/qualified-difference-events-v2.jsonl']:discovery_graph.assert_relationships(db,rows(path))
 status=core.catalog_status(db);revision=collector_journey.catalog_revision(db)
 graph=dict(db.execute("SELECT review_status,count(*) FROM card_relationship_assertion WHERE relation_type='same_artwork' AND NOT EXISTS(SELECT 1 FROM card_relationship_assertion n WHERE n.left_card_id=card_relationship_assertion.left_card_id AND n.right_card_id=card_relationship_assertion.right_card_id AND n.relation_type=card_relationship_assertion.relation_type AND n.rowid>card_relationship_assertion.rowid) GROUP BY review_status").fetchall())
 coordinates=db.execute('SELECT count(*) FROM (SELECT DISTINCT language,set_code,collector_number FROM card)').fetchone()[0]
 manifest=json.loads(Path('catalog-build-manifest-source-facts-thousand-v1.json').read_text());assert len(manifest['steps'])==57
 for operation,path in [('import-number-reading-evidence',r/'number-evidence-v1.jsonl'),('import-source-image-facts',r/'evidence-v1.jsonl'),('import-reviewed-relationships',Path('catalog/cross-release-artwork-v1/verified-artwork-events-v2.jsonl')),('import-reviewed-relationships',Path('catalog/cross-release-artwork-v1/qualified-difference-events-v2.jsonl'))]:manifest['steps'].append(dict(operation=operation,path=str(path),sha256=hashlib.sha256(path.read_bytes()).hexdigest()))
 manifest['expected'].update(status['number_reading_evidence']);manifest['expected'].update(status['source_image_facts'])
 manifest['expected']['relationship_assertions']=db.execute('SELECT count(*) FROM card_relationship_assertion').fetchone()[0];manifest['expected']['verified_relationships']=db.execute("SELECT count(*) FROM card_relationship_assertion WHERE review_status='verified'").fetchone()[0]
 manifest['description']='Preserve all 57 previous ordered inputs. Append 308 separately recorded Astra/Gemini source-image readings, 9 qualified exact-source artwork matches and 3 qualified differences; retain old OCR histories, title/number uncertainties and 24 missing-asset holds. No physical or price approvals.'
 Path('catalog-build-manifest-source-facts-escalation-v1.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
(r/'coverage-working-v1.json').write_text(json.dumps(dict(catalog_status=status,catalog_revision=revision,coordinates=coordinates,latest_artwork_states=graph,new_catalog_identities_added=0,new_number_revisions=308,new_source_fact_revisions=308,new_same_artwork_edges=9,new_qualified_differences=3),ensure_ascii=False,indent=2)+'\n')
comp=json.loads((r/'compilation-v1.json').read_text());missing=rows(r/'missing-targets-v1.jsonl');comp['outcomes'] += [dict(target_id=x['target_id'],card_id=x['endpoint_snapshot']['card_id'],status='held',reason='source_asset_unavailable',number_event_id=None,source_fact_event_id=None) for x in missing];comp['subjects']=332;comp['available_images']=308;comp['missing_assets']=24;(r/'complete-outcomes-v1.json').write_text(json.dumps(comp,ensure_ascii=False,indent=2)+'\n')
a=Path('catalog/cross-release-artwork-v1');summary=json.loads((a/'adjudication-v1.json').read_text());summary['final_holds']=[dict(candidate_id='cross-artwork-013',reason='prism_title_symbol_unconfirmed'),dict(candidate_id='cross-artwork-014',reason='printed_title_mismatch_and_unparsed_adjacent_rarity_text')];summary['correction_of']='adjudication-v1.json hold descriptions; events unchanged';(a/'adjudication-v2.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(dict(numbers=status['number_reading_evidence'],facts=status['source_image_facts'],graph=graph),ensure_ascii=False))
